import{z as A,x as B,o as E,c as d,q as t,j as n,D as e,d as r,s,S as i,b as o}from"./chunks/framework.C8m1ZpeB.js";const k=JSON.parse('{"title":"布隆过滤器","description":"","frontmatter":{"title":"布隆过滤器","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/bloom-filter.md","filePath":"cs/bloom-filter.md","lastUpdated":1791413859000}'),p={name:"cs/bloom-filter.md"};function m(D,a,f,h,u,c){const l=B("Mermaid");return E(),d("div",null,[a[2]||(a[2]=t('<h1 id="布隆过滤器" tabindex="-1">布隆过滤器 <a class="header-anchor" href="#布隆过滤器" aria-label="Permalink to &quot;布隆过滤器&quot;">​</a></h1><div class="epigraph"><p>只问「可能在集合里吗」，允许把真正在的说成在、把不在的偶尔说成在；换来的是远小于存全体键的那一块位图。</p><footer>—— 据 Bloom, Space/Time Trade-offs in Hash Coding with Allowable Errors, CACM 1970 整理</footer></div><p><a href="/cs/robin-cuckoo">上一课</a>仍是精确字典：查到就是在，碰不到就是不在。<a href="/cs/hash-function">散列函数</a>给出 \\(h(k)\\)。本课不重讲探测序列。缺口是近似集：Bloom 用 \\(m\\) 位数组和 \\(k\\) 个散列，插入置位，查询若有一位为 0 则<strong>一定不在</strong>，全为 1 则<strong>可能在</strong>（假阳性）。跳表下一课回到精确有序结构；本课不保序、不存键。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>缓存、路由、数据库里经常先问「这个键有没有可能命中后面那份昂贵结构」。存完整散列集会太大。缺口不是再开一张布谷表，而是<strong>允许单侧错误</strong>：假阳性可接受，假阴性不可（标准 Bloom 无删除则不会假阴）。空间约 \\(m\\) 比特，与 \\(n\\) 和目标误差 \\(\\varepsilon\\) 有关，远小于存键。</p><p>删除：清位会误伤其他键。标准结构不支持删；计数 Bloom 是附录。</p><p><span class="marginnote">术语翻译：<strong>假阳性</strong>是把不在集里的说成「可能在」（误报，多查一次而已）；<strong>假阴性</strong>是把真在的说成「不在」（漏报，数据就丢了）。布隆的设计原则是只肯犯前一种错。</span></p><p><span class="marginnote">Bloom 1970 原文就是「允许错误的散列编码」。\\(k\\) 个独立均匀散列是分析假设；实践用两个散列派生多个下标。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p><code>insert(x)</code>：对 \\(i=1..k\\) 置 <code>B[h_i(x)]=1</code>。<code>query(x)</code>：若某 <code>h_i(x)</code> 为 0 则否；否则报「可能」。假阳性率约 \\((1-e^{-kn/m})^k\\)，给定 \\(m,n\\) 可挑 \\(k\\) 使误差近最小（约 \\(k=(m/n)\\ln 2\\)）。本课不把求导写进主干，只钉误差随 \\(m/n\\) 与 \\(k\\) 降。</p>',10)),(E(),n(i,null,{default:e(()=>[s(l,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20X%5B%22%E9%94%AE%20x%22%5D%20--%3E%20H%5B%22k%20%E4%B8%AA%E4%B8%8B%E6%A0%87%22%5D%0A%20%20H%20--%3E%20SET%5B%22%E6%8F%92%E5%85%A5%EF%BC%9A%E9%82%A3%E4%BA%9B%E4%BD%8D%E7%BD%AE%E7%BD%AE%201%22%5D%0A%20%20H%20--%3E%20Q%5B%22%E6%9F%A5%E8%AF%A2%EF%BC%9A%E6%9C%89%200%20%E5%88%99%E4%B8%80%E5%AE%9A%E4%B8%8D%E5%9C%A8%22%5D%0A%20%20Q%20--%3E%20FP%5B%22%E5%85%A8%201%EF%BC%9A%E5%8F%AF%E8%83%BD%E5%81%87%E9%98%B3%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[r(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o("p",null,"与精确表串联：布隆说不在则跳过；说可能再查真字典。假阳只浪费一次精确查找。",-1)),a[4]||(a[4]=o("p",null,[o("span",{class:"marginnote"},"数字实例：取 \\(m/n=10\\)、\\(k=7\\)，误差约 \\((1-e^{-0.7})^7\\approx 0.008\\)，即每千次查询约 8 次误报——代价是每个键只摊 10 个比特。存键本身哪怕 8 字节也是 64 比特，省了 6 倍以上。")],-1)),a[5]||(a[5]=o("h2",{id:"机制",tabindex:"-1"},[r("机制 "),o("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=o("p",null,"不存键，故不能迭代集合、不能返回卫星数据。这与字典合同不同，跳课的人若当 hashset 用会丢数据。局部性：一次查询碰 \\(k\\) 个可能分散的位，cache 行为不如线性探测；\\(m\\) 若适合放进 SRAM 则仍快。",-1)),a[7]||(a[7]=o("p",null,"再散列或扩容位图要重建，不能像动态数组那样只复制旧位——散列下标依赖 \\(m\\)。",-1)),a[8]||(a[8]=o("p",null,"假阳性从哪来？不同键的散列下标会撞到同几位，位是共享的、又不记归属，查询者无从分辨某盏「灯」是谁开的。",-1)),(E(),n(i,null,{default:e(()=>[s(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%8F%92%E5%85%A5%E9%94%AE%20x%22%5D%20--%3E%20A1%5B%22%E4%BD%8D%203%20%E7%BD%AE%201%22%5D%0A%20%20A%20--%3E%20A2%5B%22%E4%BD%8D%207%20%E7%BD%AE%201%22%5D%0A%20%20B%5B%22%E6%8F%92%E5%85%A5%E9%94%AE%20y%22%5D%20--%3E%20B1%5B%22%E4%BD%8D%207%20%E7%BD%AE%201%22%5D%0A%20%20B%20--%3E%20B2%5B%22%E4%BD%8D%2011%20%E7%BD%AE%201%22%5D%0A%20%20C%5B%22%E6%9F%A5%E8%AF%A2%20z%EF%BC%88%E4%B8%8D%E5%9C%A8%E9%9B%86%E5%90%88%EF%BC%89%22%5D%20--%3E%20D%7B%22%E4%BD%8D%203%E3%80%817%E3%80%8111%20%E5%85%A8%E4%B8%BA%201%EF%BC%9F%22%7D%0A%20%20D%20--%3E%7C%22%E6%98%AF%22%7C%20E%5B%22%E8%AF%AF%E6%8A%A5%E3%80%8C%E5%8F%AF%E8%83%BD%E5%9C%A8%E3%80%8D%EF%BC%9A%E5%81%87%E9%98%B3%E6%80%A7%22%5D%0A%20%20D%20--%3E%7C%22%E5%90%A6%22%7C%20F%5B%22%E4%B8%80%E5%AE%9A%E4%B8%8D%E5%9C%A8%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[r(" Loading... ",-1)])]),_:1})),a[9]||(a[9]=t('<p><span class="marginnote">直觉类比：把位图想成一排灯的走廊，每个键按自己的口令开几盏灯；查询时只看灯亮不亮，不记是谁开的——别的键留下的亮灯，就会让陌生人误以为自己登记过。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 cuckoo filter 的指纹、不把密码学哈希当必须。也不进入大模型词表或量化栏的「权重量化」——那是另一栏。安全栏的哈希抗碰撞与这里的均匀位图不是同一需求。</p><p>后课默认：只需过滤的否定查询用布隆。要精确有序字典且不想旋转，下一课跳表用随机层高。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>布隆：位图 + 多散列；无假阴（无删时），有假阳。</li><li>不存键，不是字典；误差由 \\(m,n,k\\) 管。</li><li>精确有序的期望对数结构是下一课跳表。</li><li>出处：Bloom, <em>CACM</em>, 1970。</li></ul>',6))])}const F=A(p,[["render",m]]);export{k as __pageData,F as default};
